<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">register</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(addon, SomeEvent.class)         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 在附属中为 SomeEvent 事件注册监听器。</span></span>
